fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since both vectors have the same length, we can zip them together
    // and compare each pair element-wise
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| (x as i32) > (y as i32))
        .collect()
}